using Clock = std::chrono::system_clock;
class Contract {                                    // continuity
public:
  const Terms& current() const { return history_.rbegin()->second; }
  const Terms* as_of(Clock::time_point on) const {
    auto it = history_.upper_bound(on);             // first version after 'on'
    return it == history_.begin() ? nullptr : &std::prev(it)->second;   // nullptr = Missing
  }
  void amend(Clock::time_point eff, const Terms& t) { history_[eff] = t; }
private:
  std::map<Clock::time_point, Terms> history_;      // ordered version history
};

