using Clock = std::chrono::system_clock;
std::vector<std::pair<Clock::time_point, Terms>> history_;   // ascending by effective
const Terms* as_of(Clock::time_point on) const {
  auto it = std::upper_bound(history_.begin(), history_.end(), on,
      [](Clock::time_point v, const std::pair<Clock::time_point, Terms>& e) { return v < e.first; });
  return it == history_.begin() ? nullptr : &std::prev(it)->second;
}
